package com.rwi.myrepublic.nisa.internal;import com.rwi.myrepublic.nisa.NisaConfig;import java.io.IOException;import java.net.URI;import java.net.http.HttpClient;import java.net.http.HttpRequest;import java.net.http.HttpResponse;import java.time.Duration;import java.util.regex.Matcher;import java.util.regex.Pattern;public class NisaAuthClient{private final NisaConfig config;private final HttpClient httpClient;public NisaAuthClient(NisaConfig config,HttpClient
httpClient){this.config=config;this.httpClient=httpClient;}public String getToken()throws IOException,InterruptedException{String url=config.getApiBaseUrl()+ "/authentication/gettoken";String body=buildAuthPayload();HttpRequest request=HttpRequest.newBuilder().uri(URI.create(url)).header("Content-Type",
"application/json").timeout(Duration.ofMillis(config.getRequestTimeout())).POST(HttpRequest.BodyPublishers.ofString(body)).build();HttpResponse<String>response=httpClient.send(request,HttpResponse.BodyHandlers.ofString());int statusCode=response.statusCode();String responseBody=response.body();if(statusCode!=200){throw new IOException("NISA authentication failed. HTTP status: "+statusCode+ " | Response: "+responseBody);}String success=extractJsonValue(responseBody,
"success");if(!"true".equalsIgnoreCase(success)){String msg=extractJsonValue(responseBody, "msg");throw new IOException("NISA authentication returned success=false. msg: "+(msg!=null?msg: "(no message)"));}String token=extractJsonValue(responseBody, "muse_token");if(token==null||token.isEmpty()){throw new IOException("NISA authentication succeeded but muse_token is missing in response");}return token;}private String buildAuthPayload(){return "{\"userid\":\""+escapeJson(config.getUsername())+
"\",\"password\":\""+escapeJson(config.getPassword())+ "\"}";}private String extractJsonValue(String json,String fieldName){Pattern quoted=Pattern.compile( "\""+Pattern.quote(fieldName)+ "\"\\s*:\\s*\"([^\"\\\\]*(?:\\\\.[^\"\\\\]*)*)\"");Matcher m=quoted.matcher(json);if(m.find()){return m.group(1).trim();}Pattern unquoted=Pattern.compile( "\""+Pattern.quote(fieldName)+ "\"\\s*:\\s*([^,}\\s\\]]+)");m=unquoted.matcher(json);if(m.find()){return m.group(1).trim();}return null;}private String
escapeJson(String value){if(value==null)return "";return value.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n").replace("\r", "\\r").replace("\t", "\\t");}}